{"content":"namespace LetUsCook.AutoWrongCensus.Options;

public static class CommandLineArgumentParser
{
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length < 1)
		{
			return dict;
		}

		var command = args[0];
		if (command.Equals("census", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length < 2)
			{
				return dict;
			}

			dict[OptionsKeys.Command] = "census";
			dict[OptionsKeys.TracePath] = args[1];
		}
		else if (command.Equals("pairs", StringComparison.OrdinalIgnoreCase))
		{
			if (args.Length < 3)
			{
				return dict;
			}

			dict[OptionsKeys.Command] = "pairs";
			dict[OptionsKeys.CensusTsvPath] = args[1];
			dict[OptionsKeys.TracePath] = args[2];
		}

		return dict;
	}

	private static class OptionsKeys
	{
		public const string Command = "AutoWrongCensus:Command";
		public const string TracePath = "AutoWrongCensus:TracePath";
		public const string CensusTsvPath = "AutoWrongCensus:CensusTsvPath";
	}
}
