{"content":"using System.Text.Json;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key set of <c>src/LetUsCook.Fdc/Lexicon/Resources/exact-overrides.json</c>, read from the
/// production assembly's embedded copy. The brief's <c>overrideKey</c> column is a key-membership
/// check on this table — data, not matcher logic — so reading the file is the production source
/// (D-014 forbids copies of the *logic*; the keys themselves are the table).
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the embedded <c>exact-overrides.json</c> from the <c>LetUsCook.Fdc</c> assembly.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Lexicon.FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var root = JsonSerializer.Deserialize<JsonElement>(reader.ReadToEnd())
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		_keys = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
		{
		}
			.Union(root.EnumerateObject().Select(p => p.Name))
			.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Whether the given key is in <c>exact-overrides.json</c> (case-insensitive).</summary>
	/// <param name="key">The normalized raw text to test.</param>
	public bool Contains(string key) => _keys.Contains(key);
}
