{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines — <b>relation</b>
/// (accepted row vs key row) and <b>site</b> (how the line was accepted) — using the production
/// helpers, never copies of their logic (D-014): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/>, <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: the raw line names a can/jar unit, the key row's state is <c>Canned</c>, the accepted row's is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name keeps only its first.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree after singularising and the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state agree, tiers agree, only the qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above held, or a field a check needed was missing.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line was accepted on the override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line was accepted on the curated path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line was accepted on the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-element list for the per-token state checks: the production helpers take a list,
	// and allocating one per token for a census of a few hundred lines is the kind of waste the
	// rule against needless allocation exists to forbid.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates the classifier over the production normalizer and the exact-overrides key set.</summary>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The relation is the first of the brief's eight that holds:
	/// no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is none of ranker/override/curated.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedDesc = FirstNonEmpty(line.ActualDescriptions),
			KeyDesc = FirstNonEmpty(line.ExpectedDescriptions),
			AcceptedTier = FirstNonEmpty(line.ActualDataTypes),
			KeyTier = FirstNonEmpty(line.ExpectedDataTypes),
			ParsedName = atom?.ParsedName ?? string.Empty,
			RawText = line.RawText,
		};

		if (atom is null)
		{
			return result;
		}

		result.Site = ClassifySite(atom, line.RawText);
		if (result.Site.Length == 0)
		{
			return result;
		}

		var keyDesc = result.KeyDesc;
		if (keyDesc.Length == 0)
		{
			result.Relation = RelationNoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(result.AcceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(result.KeyTier));
		result.KeyHead = string.Join(' ', KeyHeadPhrase(keyTokens));

		if (result.AcceptedDesc.Length == 0)
		{
			result.Relation = RelationOther;
			result.MissingField = "actualDescriptions";
			return result;
		}

		var acceptedParsed = FdcDescriptionParser.Parse(result.AcceptedDesc, DatasetOf(result.AcceptedTier));
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(atom.ParsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			result.Relation = RelationPackUnitState;
			return result;
		}

		if (keyPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = RelationCompoundHeadLost;
			return result;
		}

		if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				result.Relation = RelationStateMismatch;
				return result;
			}

			if (result.KeyTier.Length == 0 || result.AcceptedTier.Length == 0)
			{
				result.Relation = RelationOther;
				result.MissingField = result.KeyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
				return result;
			}

			if (!string.Equals(result.KeyTier, result.AcceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RelationRowChoiceTier;
				return result;
			}

			result.Relation = RelationSameHeadOtherQualifier;
			var keyQualifiers = SingularPhraseList(keyParsed.Qualifiers);
			var acceptedQualifiers = SingularPhraseList(acceptedParsed.Qualifiers);
			result.KeyOnlyQualifiers = keyQualifiers.Where(q => !acceptedQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).ToList();
			result.AcceptedOnlyQualifiers = acceptedQualifiers.Where(q => !keyQualifiers.Contains(q, StringComparer.OrdinalIgnoreCase)).ToList();
			return result;
		}

		result.Relation = RelationSiblingFood;
		return result;
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first word the
	/// production state/modifier vocabulary treats as a state word. A compound food name
	/// ("bread crumbs") keeps its identity words; a state word ("dry", "blanched") ends the phrase.
	/// </summary>
	/// <param name="tokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);

		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// Normalizes a phrase and singularizes each token with the production helpers.
	/// </summary>
	/// <param name="text">The phrase to fold.</param>
	/// <returns>The normalized, singularized tokens.</returns>
	public IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	/// <summary>
	/// Folds a raw line text for the <c>exact-overrides.json</c> raw-key lookup the same way the
	/// production override path does: lower-cased, trimmed, content from the first <c>(</c> dropped.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);

		var text = rawText.Trim();
		var parenIndex = text.IndexOf('(', StringComparison.Ordinal);
		if (parenIndex >= 0)
		{
			text = text[..parenIndex];
		}

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override-lookup folding.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would accept the parsed name against the linked master — the stderr summary's reuse-site statistic.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The atom's linked master slug.</param>
	/// <returns>Whether <c>ShouldReuse</c> holds; <see langword="false"/> when either side is empty.</returns>
	public static bool ReuseRuleHolds(string parsedName, string? linkedIngredientId)
	{
		if (string.IsNullOrWhiteSpace(parsedName) || string.IsNullOrWhiteSpace(linkedIngredientId))
		{
			return false;
		}

		return IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);
	}

	/// <summary>
	/// The dataset tier of a row from its trace <c>dataType</c> string; <see cref="FdcDataset.None"/> when unparseable.
	/// </summary>
	/// <param name="dataType">The trace tier string.</param>
	/// <returns>The tier.</returns>
	public static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse<FdcDataset>(dataType, out var dataset) ? dataset : FdcDataset.None;

	private string ClassifySite(TraceAtom atom, string rawText)
	{
		return atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	private string ClassifySiteWithOverrideKey(TraceAtom atom, string rawText)
	{
		var site = ClassifySite(atom, rawText);
		if (site == SiteOverride)
		{
			return _overrideKeys.IsKey(FoldForOverrideKey(rawText)) ? "override:yes" : "override:no";
		}

		return site;
	}

	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private bool IsStateOrModifierWord(string token)
	{
		var lexicon = FdcLexicon.Default;
		if (lexicon.ModifierWords.Contains(token) || lexicon.PreparationStates.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string FirstNonEmpty(IReadOnlyList<string> values)
	{
		foreach (var value in values)
		{
			if (!string.IsNullOrWhiteSpace(value))
			{
				return value;
			}
		}

		return string.Empty;
	}
}
