{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — relation (accepted row vs key row) and site
/// (where the line was accepted) — by calling the production helpers, never copies of them (D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/> for tokens,
/// <see cref="FdcMatcher.ExtractCandidateState(System.Collections.Generic.IReadOnlyList{string})"/> and
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(System.Collections.Generic.IReadOnlyList{string})"/> for state masks,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/> for head terms, and
/// <see cref="IngredientLineResolver.SingularizeToken(string)"/> for singularising.
/// <para>
/// The relation order is the brief's: the first rule that holds wins — <c>no-label</c>,
/// <c>pack-unit-state</c>, <c>compound-head-lost</c>, <c>state-mismatch</c>, <c>row-choice-tier</c>,
/// <c>same-head-other-qualifier</c>, <c>sibling-food</c>, <c>other</c>.
/// </para>
/// <para>
/// <b>Key head phrase</b> (the <c>keyHead</c> column and the <c>compound-head-lost</c> test): the key
/// description's normalised tokens up to the first token that the production lexicon or state
/// extraction calls a state/modifier word (<see cref="FdcLexicon.ModifierWords"/>, or a token whose
/// single-token <c>ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c> mask is non-zero).
/// "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>; "Nuts, almonds, blanched" →
/// <c>nut almond</c> ("blanched" is a modifier word). The parser's own single-token <c>HeadTerm</c>
/// cannot express the compound, so the phrase is the census's head notion; the parser <c>HeadTerm</c>
/// is still used for the <c>state-mismatch</c>/<c>sibling-food</c> head comparison.
/// </para>
/// Not thread-safe: one shared scratch slot feeds the per-token state calls.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: a can/jar unit line accepted on a row whose state mask lacks <c>Canned</c>.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is compound and the parsed name kept only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; only non-state qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: none of the above held, or a field a check needed was missing.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused an existing master/row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the line was accepted through the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the line was accepted through the curated catalogue.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the line was accepted by the ranker without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Scratch slot for the per-token state calls; the classifier is single-threaded.</summary>
	private readonly string?[] _singleTokenScratch = new string[1];

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>Creates a classifier over the production normalizer.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>Classifies one auto-wrong line.</summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = FirstNonEmpty(line.ExpectedDescriptions);
		var acceptedDesc = FirstNonEmpty(line.ActualDescriptions);
		var keyTier = FirstNonEmpty(line.ExpectedDataTypes);
		var acceptedTier = FirstNonEmpty(line.ActualDataTypes);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedStateMask(keyTokens);
		var acceptedState = CombinedStateMask(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
			? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

		var keyHeadTokens = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHeadTokens = SingularPhrase(acceptedParsed.HeadTerm);
		var parsedNameTokens = SingularPhrase(FirstAtom(line).ParsedName);

		var relation = ClassifyRelation(
			line.RawText,
			keyDesc,
			acceptedDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			keyHeadPhrase,
			keyHeadTokens,
			acceptedHeadTokens,
			parsedNameTokens,
			keyParsed,
			acceptedParsed,
			out string? missingField);

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = ClassifySite(line),
			OverrideKey = ClassifySite(line) == SiteOverride ? (IsOverrideKey(line.RawText) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = FirstAtom(line).ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = relation == RelationSameHeadOtherQualifier ? QualifierDiff(keyParsed, acceptedParsed, out _) : null,
			AcceptedOnlyQualifiers = relation == RelationSameHeadOtherQualifier ? QualifierDiff(acceptedParsed, keyParsed, out _) : null,
		};
	}

	/// <summary>
	/// The key head phrase: normalised key tokens up to the first token the production lexicon/state
	/// extraction treats as a state or modifier word, each singularised.
	/// </summary>
	/// <param name="keyTokens">The key description's normalised tokens.</param>
	/// <returns>The singularised head-phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		var phrase = new List<string>(keyTokens.Count);
		for (var i = 0; i < keyTokens.Count; i++)
		{
			if (CarriesStateOrModifier(keyTokens[i]))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(keyTokens[i]));
		}

		return phrase;
	}

	/// <summary>
	/// The combined state mask exactly as the matcher composes it:
	/// <c>ExtractCandidateState(tokens) | ExtractCandidateSatisfiers(tokens)</c>.
	/// </summary>
	/// <param name="tokens">The row description's normalised tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedStateMask(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private string ClassifySite(TraceLine line)
	{
		var atom = FirstAtom(line);
		return atom.Path.ToLowerInvariant() switch
		{
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		string rawText,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHeadPhrase,
		IReadOnlyList<string> keyHeadTokens,
		IReadOnlyList<string> acceptedHeadTokens,
		IReadOnlyList<string> parsedNameTokens,
		ParsedFdcDescription keyParsed,
		ParsedFdcDescription acceptedParsed,
		out string? missingField)
	{
		missingField = null;

		// 1. no-label.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return RelationNoLabel;
		}

		// 2. pack-unit-state: a can/jar unit line whose key carries Canned and the accepted row does not.
		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) != 0
			&& (acceptedState & FoodState.Canned) == 0)
		{
			return RelationPackUnitState;
		}

		// 3. compound-head-lost: the key head phrase is compound and the parsed name kept only its first word.
		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return RelationCompoundHeadLost;
		}

		if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			missingField = "actualDescriptions";
			return RelationOther;
		}

		var headsAgree = keyHeadTokens.SequenceEqual(acceptedHeadTokens, StringComparer.OrdinalIgnoreCase);
		if (headsAgree)
		{
			// 4. state-mismatch.
			if (keyState != acceptedState)
			{
				return RelationStateMismatch;
			}

			if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
				return RelationOther;
			}

			// 5. row-choice-tier.
			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				return RelationRowChoiceTier;
			}

			// 6. same-head-other-qualifier.
			return RelationSameHeadOtherQualifier;
		}

		// 7. sibling-food.
		return RelationSiblingFood;
	}

	private static string FirstAtomText(TraceAtom atom) => atom.ParsedName;

	private static TraceAtom FirstAtom(TraceLine line)
	{
		if (line.Atoms.Count == 0)
		{
			throw new InvalidOperationException($"Trace line {line.HoldoutId}#{line.LineIndex} has no atoms.");
		}

		return line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms[0];
	}

	private static string FirstNonEmpty(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private static bool IsOverrideKey(string rawText)
	{
		// The production raw-key lookup folds the same way (FdcMatcher.MatchAsync): lower-case, trim,
		// content from the first '(' dropped. StripFromParenthesis itself is private, so the one-line
		// fold is applied here against the production key set (brief §8: nearest wrapper).
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var folded = (index >= 0 ? rawText[..index] : rawText).Trim().ToLowerInvariant();
		return folded.Length > 0;
	}

	private bool IsOverrideKeyHit(string rawText)
	{
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var folded = (index >= 0 ? rawText[..index] : rawText).Trim().ToLowerInvariant();
		return _overrideKeys.IsKey(folded);
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool CarriesStateOrModifier(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private static IReadOnlyList<string> QualifierDiff(ParsedFdcDescription side, ParsedFdcDescription other, out _ _)
	{
		var otherSet = new HashSet<string>(other.Qualifiers, StringComparer.OrdinalIgnoreCase);
		return side.Qualifiers.Where(q => !otherSet.Contains(q)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(q => q, StringComparer.Ordinal).ToArray();
	}
}
