{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Parsing;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Console sinks for the census: TSV on <see cref="Output"/>, summary/diagnostics on <see cref="Error"/>.</summary>
/// <param name="Output">The TSV sink (stdout).</param>
/// <param name="Error">The summary/diagnostics sink (stderr).</param>
public sealed record OutputWriters(TextWriter Output, TextWriter Error)
{
	/// <summary>The process defaults: <see cref="System.Console.Out"/> and <see cref="System.Console.Error"/>.</summary>
	public static OutputWriters Console => new(System.Console.Out, System.Console.Error);
}

/// <summary>Runs one census or pairs invocation.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the invocation; the return value is the process exit code.</summary>
	/// <param name="stoppingToken">Host stopping token.</param>
	/// <returns>0 on success, 1 on a missing file, a refused set, or a malformed invocation.</returns>
	Task<int> RunAsync(CancellationToken stoppingToken);
}

/// <summary>
/// Reads a HoldoutGate trace, classifies every auto-wrong line, writes the TSV to
/// <see cref="OutputWriters.Output"/> and the relation × site summary to <see cref="OutputWriters.Error"/>.
/// </summary>
public sealed class AutoWrongCensusRunner(
	AutoWrongCensusOptions options,
	AutoWrongClassifier classifier,
	FdcNormalizer normalizer,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private const string CensusHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";
	private const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";
	private static readonly string[] AllowedSets = ["debug", "batch"];

	private readonly TextWriter _output = writers.Output;
	private readonly TextWriter _error = writers.Error;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken stoppingToken)
	{
		try
		{
			return options.Command switch
			{
				CommandLineArgumentParser.CensusCommand => await RunCensusAsync(stoppingToken).ConfigureAwait(false),
				CommandLineArgumentParser.PairsCommand => await RunPairsAsync(stoppingToken).ConfigureAwait(false),
				_ => UnusableInvocation(),
			};
		}
		catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
		{
			return 1;
		}
		catch (Exception ex) when (ex is IOException or InvalidOperationException)
		{
			_error.WriteLine($"error: {ex.Message}");
			return 1;
		}
	}

	private int UnusableInvocation()
	{
		_error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
		return 1;
	}

	private async Task<int> RunCensusAsync(CancellationToken stoppingToken)
	{
		var lines = await ReadTraceAsync(options.TracePath, stoppingToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		_output.WriteLine(CensusHeader);

		var results = new List<ClassificationResult>(lines.Count);
		var unknownSite = 0;
		foreach (var line in lines)
		{
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSite++;
				_error.WriteLine($"unknown decision path '{line.Atoms[0].Path}' for {line.HoldoutId}#{line.LineIndex}");
				continue;
			}

			results.Add(result);
			_output.WriteLine(ToTsv(result));
		}

		await _output.FlushAsync(stoppingToken).ConfigureAwait(false);
		_writeCensusSummary(lines, results);

		if (unknownSite > 0)
		{
			return 1;
		}

		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken stoppingToken)
	{
		var lines = await ReadTraceAsync(options.TracePath, stoppingToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var censusRows = ReadCensusTsv(options.CensusTsvPath);
		if (censusRows is null)
		{
			return 1;
		}

		var byLine = new Dictionary<(string, int), TraceLine>(lines.Count);
		foreach (var line in lines)
		{
			byLine[(line.HoldoutId, line.LineIndex)] = line;
		}

		_output.WriteLine(PairsHeader);
		var emitted = 0;
		var unmatched = 0;
		foreach (var (holdoutId, lineIndex) in censusRows)
		{
			if (!byLine.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				_error.WriteLine($"no trace line for {holdoutId}#{lineIndex}");
				continue;
			}

			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(line.Atoms[0].ParsedName)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			_output.WriteLine($"{Cell(line.HoldoutId)}\t{line.LineIndex}\t{Cell(parsedNameHead)}\t{Cell(keyHead)}\t{Cell(line.RawText)}");
			emitted++;
		}

		await _output.FlushAsync(stoppingToken).ConfigureAwait(false);
		_error.WriteLine($"pairs: {emitted} emitted, {unmatched} census rows without a trace line");
		return 0;
	}

	private void _writeCensusSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results)
	{
		var set = lines.Count > 0 ? lines[0].Set : "?";
		_error.WriteLine($"autoWrongCensus set={set} traceLines={lines.Count} autoWrong={results.Count}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			_error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_error.WriteLine($"other rate: {other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField);
		_error.WriteLine(missing.Any()
			? "missing fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}"))
			: "missing fields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		_error.WriteLine($"overrideKey hits: {overrideLines.Count(r => r.OverrideKey == "yes")}/{overrideLines.Count}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseRejected = 0;
		var reuseCounted = 0;
		foreach (var r in reuseLines)
		{
			if (r.ParsedName.Length == 0)
			{
				continue;
			}

			reuseCounted++;
			if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), r.ParsedName))
			{
				reuseRejected++;
			}
		}

		_error.WriteLine($"reuse lines where the resolver's own ShouldReuse rejects the name: {reuseRejected}/{reuseCounted}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		_error.WriteLine($"row-choice-tier: key higher={keyHigher} accepted higher={tierLines.Count - keyHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			var keyOnly = string.Join(' ', r.KeyOnlyQualifiers ?? []);
			var acceptedOnly = string.Join(' ', r.AcceptedOnlyQualifiers ?? []);
			_error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex} key-only=[{keyOnly}] accepted-only=[{acceptedOnly}]");
		}
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken stoppingToken)
	{
		if (path.Length == 0 || !File.Exists(path))
		{
			_error.WriteLine($"error: trace file not found at '{path}'");
			return null;
		}

		var lines = new List<TraceLine>();
		var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		await foreach (var line in File.ReadLinesAsync(path, stoppingToken).ConfigureAwait(false))
		{
			stoppingToken.ThrowIfCancellationRequested();
			if (line.Length == 0)
			{
				continue;
			}

			try
			{
				var record = JsonSerializer.Deserialize<TraceLine>(line, jsonOptions);
				if (record is null)
				{
					continue;
				}

				lines.Add(record);
			}
			catch (JsonException ex)
			{
				_error.WriteLine($"error: malformed trace line at {path}: {ex.Message}");
				return null;
			}
		}

		var refused = lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).FirstOrDefault(s => !AllowedSets.Contains(s, StringComparer.Ordinal));
		if (refused is not null)
		{
			_error.WriteLine($"refused: trace set '{refused}' is not debug or batch (D-029: no sealed read)");
			return null;
		}

		return lines;
	}

	// P12.7 blocker-census TSV: keep the rows whose blocker is window and route is compound or other.
	private (string HoldoutId, int LineIndex)[]? ReadCensusTsv(string path)
	{
		if (path.Length == 0 || !File.Exists(path))
		{
			_error.WriteLine($"error: census TSV not found at '{path}'");
			return null;
		}

		var lines = File.ReadLines(path).ToList();
		if (lines.Count < 2)
		{
			_error.WriteLine($"error: census TSV at '{path}' has no rows");
			return null;
		}

		var header = lines[0].Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf[header[i]] = i;
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				_error.WriteLine($"error: census TSV at '{path}' is missing column '{required}'");
				return null;
			}
		}

		var rows = new List<(string, int)>();
		foreach (var line in lines.Skip(1))
		{
			var cells = line.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (cells[indexOf["blocker"]] != "window" || (cells[indexOf["route"]] != "compound" && cells[indexOf["route"]] != "other"))
			{
				continue;
			}

			if (int.TryParse(cells[indexOf["lineIndex"]], out var lineIndex))
			{
				rows.Add((cells[indexOf["holdoutId"]], lineIndex));
			}
		}

		return rows.ToArray();
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"slegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Cell(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string ToTsv(ClassificationResult r) => string.Join('\t',
		Cell(r.HoldoutId),
		r.LineIndex,
		Cell(r.Set),
		Cell(r.Relation),
		Cell(r.Site),
		Cell(r.OverrideKey),
		Cell(r.AcceptedTier),
		Cell(r.KeyTier),
		Cell(r.AcceptedState),
		Cell(r.KeyState),
		Cell(r.ParsedName),
		Cell(r.KeyHead),
		Cell(r.AcceptedDesc),
		Cell(r.KeyDesc),
		Cell(r.RawText));
}
