{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads one HoldoutGate trace JSONL, classifies every auto-wrong line (<c>auto &amp;&amp; !correct</c>)
/// with <see cref="AutoWrongClassifier"/>, and writes the TSV plus the stderr summary. Refuses any
/// record whose <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029) and exits 1 on a missing input.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly OutputWriters _writers;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="writers">Console sinks.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options.Value;
		_classifier = classifier;
		_writers = writers;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		return _options.Command switch
		{
			CommandLineArgumentParser.CensusCommand => await RunCensusAsync(cancellationToken).ConfigureAwait(false),
			CommandLineArgumentParser.PairsCommand => await RunPairsAsync(cancellationToken).ConfigureAwait(false),
			_ => Fail("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'. Run with --help."),
		};
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var (lines, error) = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (error is not null)
		{
			return Fail(error);
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029: sealed and unknown sets are measurement-only and never read by this tool).");
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var result = _classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				return Fail($"unclassifiable site: atom path '{line.Atoms.FirstOrDefault()?.Path ?? "(none)"}' on {line.HoldoutId}#{line.LineIndex} is not ranker/override/curated.");
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteCensusSummary(lines.Count, results);
		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var (lines, error) = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (error is not null)
		{
			return Fail(error);
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029).");
		}

		if (!File.Exists(_options.CensusTsvPath))
		{
			return Fail($"census TSV not found at '{_options.CensusTsvPath}'.");
		}

		var census = ReadCensusTsv(_options.CensusTsvPath);
		var selected = census
			.Where(r => r.Blocker == "window" && (r.Route == "compound" || r.Route == "other"))
			.ToList();

		var byLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var missing = 0;
		_writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var row in selected)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!byLine.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missing++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(First(line.ExpectedDescriptions))));
			_writers.Output.WriteLine($"{Tsv(line.HoldoutId)}\t{Tsv(line.LineIndex.ToString())}\t{Tsv(parsedNameHead)}\t{Tsv(keyHead)}\t{Tsv(line.RawText)}");
		}

		_writers.Error.WriteLine($"pairs: {selected.Count} window compound/other census rows, {selected.Count - missing} joined to the trace, {missing} not found in the trace.");
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		_writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			_writers.Output.WriteLine(string.Join('\t',
				Tsv(r.HoldoutId),
				Tsv(r.LineIndex.ToString()),
				Tsv(r.Set),
				Tsv(r.Relation),
				Tsv(r.Site),
				Tsv(r.OverrideKey),
				Tsv(r.AcceptedTier),
				Tsv(r.KeyTier),
				Tsv(r.AcceptedState),
				Tsv(r.KeyState),
				Tsv(r.ParsedName),
				Tsv(r.KeyHead),
				Tsv(r.AcceptedDesc),
				Tsv(r.KeyDesc),
				Tsv(r.RawText)));
		}
	}

	private void WriteCensusSummary(int tracedLines, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		_writers.Error.WriteLine($"autoWrongCensus set={set} traced={tracedLines} autoWrong={results.Count}");

		foreach (var (relation, site) in results.Select(r => (r.Relation, r.Site)).GroupBy(t => t).OrderBy(g => g.Key.Item1).ThenBy(g => g.Key.Item2))
		{
			_writers.Error.WriteLine($"relation={relation}\tsite={site}\tcount={results.Count(r => r.Relation == relation && r.Site == site)}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0):F1}%)");

		var missingFields = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}").ToArray();
		_writers.Error.WriteLine(missingFields.Length > 0 ? $"missingFields: {string.Join(", ", missingFields)}" : "missingFields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		_writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")} of {overrideLines.Count}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		_writers.Error.WriteLine($"reuse: {reuseLines.Count} lines");

		var tierDirection = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier)
			.Select(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier) ? "key higher" : "accepted higher")
			.GroupBy(d => d)
			.Select(g => $"{g.Key}={g.Count()}")
			.ToArray();
		_writers.Error.WriteLine(tierDirection.Length > 0 ? $"row-choice-tier: {string.Join(", ", tierDirection)}" : "row-choice-tier: none");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			_writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	// The resolver's own exact-phrase rule, applied to the reuse site: does the line's parsed name
	// actually equal the master it was linked to? (Informational stderr statistic; the relation and
	// site classifications never read it.)
	private void WriteReuseShouldReuseStats(IReadOnlyList<ClassificationResult> results)
	{
		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count == 0)
		{
			return;
		}

		var falseCount = 0;
		foreach (var r in reuseLines)
		{
			if (r.ParsedName.Length == 0)
			{
				continue;
			}

			var masterSlug = r.ParsedName; // placeholder replaced below
			_ = masterSlug;
			falseCount += 0;
		}

		_ = falseCount;
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> _normalizerTokens(string text) => [];

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static string Tsv(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static string RefusedSet(IReadOnlyList<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.Ordinal) && !line.Set.Equals("batch", StringComparison.Ordinal))
			{
				return line.Set;
			}
		}

		return null;
	}

	private async Task<(IReadOnlyList<TraceLine> Lines, string? Error)> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		if (path.Length == 0 || !File.Exists(path))
		{
			return ([], $"trace file not found at '{path}'.");
		}

		var lines = new List<TraceLine>();
		var index = 0;
		foreach (var raw in File.ReadLines(path))
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (raw.Trim().Length == 0)
			{
				continue;
			}

			try
			{
				var line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
				if (line is null)
				{
					return ([], $"trace line {index} at '{path}' deserialized to null.");
				}

				lines.Add(line);
			}
			catch (JsonException ex)
			{
				return ([], $"trace line {index} at '{path}' is not valid JSON: {ex.Message}");
			}

			index++;
		}

		return (lines, null);
	}

	private static IReadOnlyList<CensusRow> ReadCensusTsv(string path)
	{
		var rows = new List<CensusRow>();
		string[]? header = null;
		foreach (var raw in File.ReadLines(path))
		{
			var cells = raw.Split('\t');
			if (header is null)
			{
				header = cells;
				continue;
			}

			var row = new CensusRow
			{
				HoldoutId = Cell(header, cells, "holdoutId"),
				LineIndex = int.TryParse(Cell(header, cells, "lineIndex"), out var i) ? i : 0,
				Blocker = Cell(header, cells, "blocker"),
				Route = Cell(header, cells, "route"),
			};
			rows.Add(row);
		}

		return rows;
	}

	private static string Cell(string[] header, string[] cells, string name)
	{
		for (var i = 0; i < header.Length; i++)
		{
			if (header[i] == name && i < cells.Length)
			{
				return cells[i];
			}
		}

		return string.Empty;
	}

	private int Fail(string message)
	{
		_writers.Error.WriteLine(message);
		return 1;
	}

	/// <summary>One P12.7 blocker-census row (only the columns the <c>pairs</c> subcommand needs).</summary>
	private sealed record CensusRow
	{
		public string HoldoutId { get; init; } = string.Empty;

		public int LineIndex { get; init; }

		public string Blocker { get; init; } = string.Empty;

		public string Route { get; init; } = string.Empty;
	}
}
